"""Compare the outputs regenerated by `make reproduce` with the committed ones.

E22: run in a fresh clone after `make reproduce`. Every tracked file under outputs/ and data/manifests/ is compared
with its committed version (git HEAD): identical, different only in run metadata (src/analysis/reproducibility.py),
different, missing, or not regenerated (not written since `--started`, by default the time recorded by
`make reproduce`). Writes outputs/reports/reproducibility.{json,md} and the package lists of both environments.
Exits 1 if any file differs or is missing.
"""

import json
import platform
import subprocess
import sys
from datetime import UTC, datetime
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from src.analysis.reproducibility import (  # noqa: E402
    METADATA_KEYS,
    METADATA_SECTIONS,
    compare_file,
    not_regenerated_reason,
    report_markdown,
    summarize,
)
from src.data.manifest import write_json  # noqa: E402
from src.evaluation.pipeline import relative  # noqa: E402
from src.metrics.tools import tool_paths, verify_manifest  # noqa: E402
from src.utils.cli import base_parser, init_run  # noqa: E402
from src.utils.config import load_config  # noqa: E402
from src.utils.paths import OUTPUT_DIR, REPO_ROOT  # noqa: E402

STARTED = OUTPUT_DIR / "logs" / "reproduce_started"
SCOPE = ["outputs", "data/manifests"]
PROCEDURE = [
    "`git clone` of the repository at the commit above into a new directory (no untracked files, no outputs other "
    "than the committed ones).",
    "New `.venv` and `.venv-metrics` created with uv from the Miniforge Python and the pinned `requirements.txt` "
    "and `requirements-metrics.txt`.",
    "`tools/` (JDK 11, metric jars, CoreNLP, checkpoints) copied from the original checkout and verified against "
    "`tools/MANIFEST.json` (SHA-256 of every file); `.env` with `CLOTHO_ROOT` only (no API keys).",
    "`make test` and `make test-metrics`.",
    "`make reproduce`: Clotho validation and manifests (E02-E03), caption consolidation and completion reports "
    "(E06-E10), metric validation (E11), five-reference, leave-one-out and four-reference scoring (E12-E14), length "
    "and statistical analyses (E15-E16), qualitative sample, annotation and audio-review analyses (E17-E19, labels "
    "as committed), examples and qualitative figures (E20), cross-metric comparison and figures (E21). No caption "
    "generation.",
    "`scripts/check_reproducibility.py`: every tracked output compared with its committed version.",
]


def git(*args: str) -> bytes:
    return subprocess.run(["git", *args], cwd=REPO_ROOT, check=True, capture_output=True).stdout


def freeze(python: Path) -> str:
    if not python.exists():
        return f"{relative(python)}: not found\n"
    result = subprocess.run(["uv", "pip", "freeze", "--python", str(python)], capture_output=True, text=True)
    return result.stdout


def main() -> int:
    parser = base_parser(__doc__.splitlines()[0])
    parser.add_argument("--started", type=float, help="Unix time the reproduction started (default: from make)")
    parser.add_argument("--reproduced-at", default="HEAD", help="commit make reproduce ran at (default: HEAD)")
    args = parser.parse_args()
    logger = init_run(Path(__file__).stem, args)
    if args.started is None and not STARTED.is_file():
        logger.error("No start time: pass --started or run make reproduce first (%s)", relative(STARTED))
        return 1
    started = args.started if args.started is not None else float(STARTED.read_text().strip())
    outputs = {
        "report_json": OUTPUT_DIR / "reports" / "reproducibility.json",
        "report_md": OUTPUT_DIR / "reports" / "reproducibility.md",
        "environment": OUTPUT_DIR / "reports" / "reproducibility_environment.txt",
    }
    own = {relative(path) for path in outputs.values()}

    tracked = [p for p in git("ls-files", "-z", *SCOPE).decode().split("\0") if p and not p.endswith(".gitkeep")]
    files = []
    for path in tracked:
        if path in own:
            continue
        old = git("show", f"HEAD:{path}")
        current = REPO_ROOT / path
        new = current.read_bytes() if current.is_file() else None
        if new is not None and current.stat().st_mtime < started:
            detail = not_regenerated_reason(path) if new == old else "changed before the run"
            row = {"path": path, "status": "not_regenerated", "detail": detail}
        else:
            row = compare_file(path, old, new)
        files.append(row)
    untracked = [p for p in git("ls-files", "-z", "--others", "--exclude-standard", *SCOPE).decode().split("\0")
                 if p and p not in own]  # fmt: skip
    files += [{"path": p, "status": "different", "detail": "new file not in the commit"} for p in untracked]
    counts = summarize(files)

    tools_problems = verify_manifest(tool_paths(load_config("metrics", args.overrides)["tools"])["root"])
    environment = {
        "Platform": platform.platform(),
        "Python": platform.python_version(),
        "Repository": str(REPO_ROOT),
        "Tools manifest": "verified" if not tools_problems else f"{len(tools_problems)} problems",
        "Reproduction started (UTC)": datetime.fromtimestamp(started, UTC).isoformat(timespec="seconds"),
    }
    environments = {"requirements.txt (.venv)": ".venv", "requirements-metrics.txt (.venv-metrics)": ".venv-metrics"}
    frozen = "".join(
        f"# {name}\n{freeze(REPO_ROOT / venv / 'bin' / 'python')}\n" for name, venv in environments.items()
    )
    report = {
        "task": "E22",
        "commit": git("rev-parse", "HEAD").decode().strip(),
        "reproduced_at": git("rev-parse", args.reproduced_at).decode().strip(),
        "same_committed_outputs": not git("diff", "--name-only", args.reproduced_at, "HEAD", "--", *SCOPE).strip(),
        "timestamp_utc": datetime.now(UTC).isoformat(timespec="seconds"),
        "procedure": PROCEDURE,
        "environment": environment,
        "metadata_keys": sorted(METADATA_KEYS),
        "metadata_sections": list(METADATA_SECTIONS),
        "counts": counts,
        "files": files,
        "outputs": {name: relative(path) for name, path in outputs.items()},
    }
    write_json(report, outputs["report_json"])
    outputs["report_md"].write_text(report_markdown(report), encoding="utf-8")
    outputs["environment"].write_text(frozen, encoding="utf-8")
    logger.info("%s", json.dumps(counts))
    for row in files:
        if row["status"] in ("different", "missing"):
            logger.error("%s: %s (%s)", row["status"], row["path"], row["detail"])
    return 0 if counts["different"] == 0 and counts["missing"] == 0 and not tools_problems else 1


if __name__ == "__main__":
    sys.exit(main())
